@using sv_2863459fcf75410284f1b5bca6ea6cd8.Models

<nav aria-label="Application progress">
    <ol class="step-indicator d-flex list-unstyled mb-4">
        @for (int i = 0; i < StepNames.Length; i++)
        {
            var step = i;
            var isCurrent = step == CurrentStep;
            var isCompleted = CompletedSteps.Contains(step);
            var isFuture = !isCurrent && !isCompleted;

            <li class="step-item flex-fill text-center @(isCurrent ? "active" : "") @(isCompleted ? "completed" : "") @(isFuture ? "future" : "")"
                @onclick="() => OnStepClick(step)"
                role="button"
                tabindex="@(isCompleted ? 0 : -1)"
                aria-current="@(isCurrent ? "step" : null)">
                <div class="step-circle mx-auto mb-1">
                    @if (isCompleted)
