                    @if (isCompleted)
                    {
                        <span>&#10003;</span>
                    }
                    else
                    {
                        <span>@(step + 1)</span>
                    }
                </div>
                <div class="step-label small">@StepNames[step]</div>
                @if (step < StepNames.Length - 1)
                {
                    <div class="step-connector"></div>
                }
            </li>
        }
    </ol>
