.step-indicator {
    counter-reset: step;
    padding: 0;
}

.step-item {
    position: relative;
    cursor: default;
}

.step-item.completed {
    cursor: pointer;
}

.step-circle {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 600;
    font-size: 0.9rem;
    border: 2px solid #dee2e6;
    background: #fff;
    color: #6c757d;
    transition: all 0.2s;
}

.step-item.active .step-circle {
    background: #0d6efd;
    border-color: #0d6efd;
    color: #fff;
}

.step-item.completed .step-circle {
    background: #198754;
    border-color: #198754;
    color: #fff;
}

.step-item.future .step-circle {
    opacity: 0.5;
}

.step-label {
    font-weight: 500;
    color: #495057;
}

.step-item.future .step-label {
    opacity: 0.5;
}

.step-item.active .step-label {
    color: #0d6efd;
    font-weight: 600;
}

.step-connector {
    position: absolute;
    top: 18px;
    left: calc(50% + 22px);
    right: calc(-50% + 22px);
    height: 2px;
    background: #dee2e6;
}

.step-item.completed .step-connector {
    background: #198754;
}

